    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }

    File[] jarFiles = dirFile.listFiles((d, name) -> name.endsWith(".jar"));
    if (jarFiles == null) {
        return;
    }

    for (File jarFile : jarFiles) {
        try {
            URL jarUrl = jarFile.toURI().toURL();
            if (!cpV.contains(jarUrl)) {
                cpV.add(jarUrl);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

@SuppressWarnings("unchecked")
public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirObj = new File(dir);
    if (!dirObj.exists() || !dirObj.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }

    File[] files = dirObj.listFiles((dir1, name) -> name.endsWith(".jar"));
    if (files == null || files.length == 0) {
        return;
    }

    URLClassLoader systemClassLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
    try {
        for (File file : files) {
            URL url = new URL("file://" + file.getAbsolutePath());
            cpV.add(url);
            Method addURLMethod = URLClassLoader.class.getDeclaredMethod("addURL", URL.class);
            addURLMethod.setAccessible(true);
            addURLMethod.invoke(systemClassLoader, url);
        }
    } catch (Exception e) {
        throw new RuntimeException("Error adding JAR files to classpath", e);
    }
}

