private int parseEndOfLine(String headerPart, int end) {
    for (int i = 0; i < end; i++) {
        if (i + 1 < end && headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end){
    if (headerPart == null) {
        throw new IllegalArgumentException("Header part cannot be null");
    }
    if (end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("End index out of bounds");
    }
    for (int i = end; i > 0; i--) {
        char currentChar = headerPart.charAt(i);
        char previousChar = headerPart.charAt(i - 1);
        if (currentChar == '\n' && previousChar == '\r') {
            return i - 1;
        }
    }
    return -1;
}

