@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }
    Set<String> keys = resultMap.keySet();
    if (keys.size() < 2) {
        throw new IllegalArgumentException("At least two vertices are required to generate a bipartite graph");
    }
    for (String key : keys) {
        if (resultMap.get(key).getPart() == null) {
            throw new IllegalArgumentException("Each vertex must belong to a part (0 or 1)");
        }
    }
    for (String key1 : keys) {
        for (String key2 : keys) {
            if (key1.equals(key2)) {
                continue;
            }
            V vertex1 = resultMap.get(key1);
            V vertex2 = resultMap.get(key2);
            if (vertex1.getPart() == vertex2.getPart()) {
                throw new IllegalArgumentException("Vertices must be in different parts");
            }
            E edge = target.addEdge(vertex1, vertex2);
            if (edge == null) {
                throw new IllegalArgumentException("Failed to add edge between vertices " + key1 + " and " + key2);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Input resultMap cannot be null or empty");
    }

    Set<V> part1 = new HashSet<>();
    Set<V> part2 = new HashSet<>();

    // Populate the two partitions based on the resultMap
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        if (entry.getKey().startsWith("Partition1")) {
            part1.add(entry.getValue());
        } else if (entry.getKey().startsWith("Partition2")) {
            part2.add(entry.getValue());
        } else {
            throw new IllegalArgumentException("Invalid partition key: " + entry.getKey());
        }
    }

    // Remove duplicate entries from resultMap
    resultMap.values().removeAll(part1);
    resultMap.values().removeAll(part2);

    // Add remaining vertices to the second partition
    part2.addAll(resultMap.values());

    // Create edges between the two partitions
    for (V v1 : part1) {
        for (V v2 : part2) {
            target.addEdge(v1, v2);
        }
    }
}

public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Assuming V is an Integer for simplicity, otherwise adjust accordingly
    int[] vertices = new int[resultMap.size() * 2];
    int index = 0;
    for (String key : resultMap.keySet()) {
        vertices[index++] = Integer.parseInt(key);
        vertices[index++] = (Integer.parseInt(key) + 1) % vertices.length;
    }

    for (int i = 0; i < vertices.length - 1; i++) {
        target.addEdge(vertices[i], vertices[i + 1], null);
    }
    target.addEdge(vertices[vertices.length - 1], vertices[0], null);
}

@Override
public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Generate a complete bipartite graph
    // Verify the input parameters
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Define the two sets of vertices for the bipartite graph
    Set<V> partition1 = new HashSet<>();
    Set<V> partition2 = new HashSet<>();

    // Populate the partitions with vertices based on resultMap
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        V vertex = entry.getValue();
        if (entry.getKey().contains("Set1")) {
            partition1.add(vertex);
        } else if (entry.getKey().contains("Set2")) {
            partition2.add(vertex);
        } else {
            throw new IllegalArgumentException("Invalid partition key");
        }
    }

    // Add edges between vertices in different partitions
    for (V v1 : partition1) {
        for (V v2 : partition2) {
            try {
                target.addEdge(v1, v2);
            } catch (DuplicateEdgeException e) {
                // Handle duplicate edge exception
            } catch (GraphException e) {
                // Handle other graph-related exceptions
            }
        }
    }

    // Add nodes to the target graph
    for (V vertex : partition1) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }

    for (V vertex : partition2) {
        if (!target.containsVertex(vertex)) {
            target.addVertex(vertex);
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Map.Entry<String, V>> entries = resultMap.entrySet();
    int n = entries.size();
    int m = n / 2; // Each partition will have n/2 vertices

    // Add vertices to the graph
    for (Map.Entry<String, V> entry : entries) {
        target.addVertex(entry.getValue());
    }

    List<V> vertices = new ArrayList<>(target.vertexSet());
    // Add edges to the graph
    for (int i = 0; i < m; i++) {
        for (int j = m; j < n; j++) {
            target.addEdge(vertices.get(i), vertices.get(j), null); // Assuming no edge properties
        }
    }
}

