public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Null parameters are not allowed");
    }
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    if (size > buffer.size()) {
        buffer = schema.newBuffer(size);
    }
    schema.writeTo(buffer, message);
    if (buffer.overflow()) {
        throw new IOException("Buffer overflow");
    }
    byte[] bufferArray = buffer.getBuffer();
    int headerSize = CodedOutputStream.computeUInt32SizeNoTag(size);
    if (headerSize > buffer.size()) {
        buffer = schema.newBuffer(headerSize + size);
    }
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    codedOut.writeUInt32NoTag(size);
    codedOut.writeRawBytes(data);
    codedOut.flush();
    out.write(bufferArray, 0, headerSize + size);
    out.flush();
    buffer.clear();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Parameters cannot be null");
    }

    try {
        byte[] messageBytes = ProtobufIOUtil.toByteArray(message, schema, buffer);
        int messageLength = messageBytes.length;

        out.writeInt(messageLength);
        out.write(messageBytes);

        return messageLength;
    } catch (IOException e) {
        throw new IOException("Error writing delimited message to output stream", e);
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Output stream, message, schema, and buffer cannot be null");
    }

    int messageSize = schema.getByteSize(message);
    byte[] messageBytes = schema.toByteArray(message);

    if (messageBytes.length > buffer.size()) {
        buffer = LinkedBuffer.allocate(buffer.estimatedSize());
    }

    int bufferSize = buffer.size();
    int writtenBytes = 0;

    // Write the length of the message
    buffer = schema.writeVarint32To(buffer, messageSize);

    writtenBytes += buffer.size() - bufferSize;

    // Write the message itself
    if (messageBytes.length <= buffer.remaining()) {
        System.arraycopy(messageBytes, 0, buffer.array(), buffer.pos(), messageBytes.length);
        buffer.advance(messageBytes.length);
    } else {
        out.write(messageBytes);
        writtenBytes += messageBytes.length;
    }

    out.write(buffer.array(), buffer.start(), buffer.length());
    writtenBytes += buffer.length();

    return writtenBytes;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Serialize the message to a byte array buffer
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    byte[] messageBytes = schema.toByteArray(message, codedOut, buffer);

    // Get the size of the serialized message
    int messageSize = messageBytes.length;

    // Write the size of the message as a varint
    codedOut.writeInt32NoTag(messageSize);

    // Write the serialized message to the output stream
    out.write(messageBytes);

    // Flush the output stream
    out.flush();

    // Return the size of the message
    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    if (size > buffer.capacity()) {
        throw new BufferOverflowException("Buffer is too small for the message");
    }
    byte[] encodedMessage = schema.toByteArray(message);
    int headerSize = CodedOutputStream.computeRawVarint32Size(size);
    if (headerSize + size > buffer.capacity()) {
        throw new BufferOverflowException("Buffer is too small for the message including the header");
    }
    out.write(CodedOutputStream.encodeZigZag32(size));
    out.write(encodedMessage);
    return size + headerSize;
}

