protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;

    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        while (start < end) {
            long nextEnd = start + FETCH_DATA_DURATION;
            if (nextEnd > end) {
                nextEnd = end;
            }
            timeRanges.add(new TimeRange(start, nextEnd));
            start = nextEnd;
        }
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration > FETCH_DATA_DURATION) {
        long interval = FETCH_DATA_DURATION;
        while (start < end) {
            if ((start + interval) > end) {
                timeRanges.add(new TimeRange(start, end));
                break;
            }
            timeRanges.add(new TimeRange(start, start + interval));
            start += interval;
        }
    } else {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    final long FETCH_DATA_DURATION = 3600000L; // 1 hour in milliseconds

    List<TimeRange> timeRanges = new ArrayList<>();

    if (start < end) {
        long currentStart = start;
        while (currentStart < end) {
            long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart = currentEnd;
