static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 10000000L || timeBucket > 99999999L) {
        throw new IllegalArgumentException("Invalid time bucket value. It should be between 10000000 and 99999999.");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Invalid dayStep. It should be greater than 0.");
    }

    long year = timeBucket / 10000;
    long month = timeBucket % 10000 / 100;
    long day = timeBucket % 100;

    switch (dayStep) {
        case 11:
            day = (day + 5) / 7 * 7 - 6;
            break;
        default:
            throw new IllegalArgumentException("Unsupported dayStep value: " + dayStep);
    }

    if (day < 1) {
        month--;
        if (month == 0) {
            month = 12;
            year--;
        }
        int daysInMonth = month == 2 ? (year % 4 == 0 ? 29 : 28) : (month < 8 ? (month % 2 == 1 ? 31 : 30) : (month % 2 == 0 ? 31 : 30));
        day += daysInMonth;
    }

    return year * 10000 + month * 100 + day;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract the year and month from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) (timeBucket % 10000 / 100);

        // Calculate the day of the month to reformat the time bucket
        int day = (int) (timeBucket % 100);

        // Calculate the new time bucket based on dayStep
        int newDay = (day - 1) / dayStep * dayStep + 1;

        // Return the re-formatted time bucket
        return (long) year * 10000 + month * 100 + newDay;
    } catch (ArithmeticException e) {
        // Handle potential overflows or arithmetic issues
        return -1;
    }
