private static File[] classPath() {
    try {
        final ClassLoader classLoader = ClassLoader.getSystemClassLoader();
        final Method method = classLoader.getClass().getDeclaredMethod("getResources", String.class);
        method.setAccessible(true);
        final Enumeration<URL> urls = (Enumeration<URL>) method.invoke(classLoader, "java.class.path");
        final List<File> classPathFiles = new ArrayList<>();
        while (urls.hasMoreElements()) {
            final URL url = urls.nextElement();
            final String path = url.getPath();
            if (path.endsWith("!/")) {
                path.pop(path.length() - 2);
            }
            classPathFiles.add(new File(path));
        }
        return classPathFiles.toArray(new File[0]);
    } catch (Exception e) {
        throw new RuntimeException("Failed to get class path", e);
    }
}

