    if(box == null){
        throw new IllegalArgumentException("Box cannot be null");
    }
    double width = box.getWidth();
    double x = box.getX();
    Box2D box1 = new Box2D(x, box.getY(), width / 2, box.getHeight());
    Box2D box2 = new Box2D(x + width / 2, box.getY(), width / 2, box.getHeight());
    return new Pair<>(box1, box2);
