public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) throws IllegalArgumentException {
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double width = box.getWidth();
    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be positive");
    }
    double centerX = box.getCenterX();
    double halfWidth = width / 2;
    Box2D box1 = new Box2D(centerX - halfWidth, box.getCenterY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(centerX, box.getCenterY(), halfWidth, box.getHeight());
    return Pair.with(box1, box2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null || box.getWidth() <= 0) {
        throw new IllegalArgumentException("Box must be non-null and have a positive width");
    }

    double halfWidth = box.getWidth() / 2;
    Box2D box1 = new Box2D(box.getX(), box.getY(), halfWidth, box.getHeight());
    Box2D box2 = new Box2D(box.getX() + halfWidth, box.getY(), halfWidth, box.getHeight());

    return Pair.with(box1, box2);
}

