    int capacity = desiredCapacity;
    while (!isPrime(capacity)) {
        capacity++;
        if (desiredCapacity >= 1000) {
            if (capacity - desiredCapacity > desiredCapacity * 0.11) {
                capacity = desiredCapacity + (int) (desiredCapacity * 0.11);
                while (!isPrime(capacity)) {
                    capacity++;
                }
                break;
            }
        }
    }
    return capacity;
}

