    }
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.node() != stop) {
        if (predicate.test(circulator.node())) {
            return circulator;
        }
        circulator = circulator.next();
    }
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes cannot be null");
    }
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (!circulator.equals(stop)) {
        if (predicate.test(circulator.node())) {
            return circulator;
        }
        circulator = circulator.cnext();
    }
    return circulator;
}

