protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    try {
        List<E> edgeList = new ArrayList<>(tour);
        if (edgeList.isEmpty()) {
            return graph.createPath();
        }

        V startVertex = graph.getEdgeSource(edgeList.get(0));
        V endVertex = graph.getEdgeTarget(edgeList.get(edgeList.size() - 1));

        GraphPath<V, E> path = graph.createPath(startVertex, endVertex);

        for (E edge : edgeList) {
            path = path.extend(edge);
        }

        return path;
    } catch (NoSuchElementException e) {
        throw new IllegalArgumentException("Edge set does not form a valid tour", e);
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph cannot be null");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createPath(); // Create an empty path
    }

    V startVertex = edges.get(0).getEdgeSource();
    V currentVertex = startVertex;
    List<E> pathEdges = new ArrayList<>();

    for (E edge : edges) {
        if (edge.getEdgeSource().equals(currentVertex)) {
            pathEdges.add(edge);
            currentVertex = edge.getEdgeTarget();
        } else if (edge.getEdgeTarget().equals(currentVertex)) {
            pathEdges.add(edge);
            currentVertex = edge.getEdgeSource();
        } else {
            return graph.createPath(); // Invalid tour, cannot form a path
        }
    }

    return graph.createPath(pathEdges);
}

