private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0;
    long currentSum = bounds.stream().mapToLong(Long::intValue).sum();

    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum -= bounds.get(i);
        suffixSumList.add(0, (int) currentSum);
        totalSum += bounds.get(i);
    }

    suffixSumList.add(0, (int) totalSum);

    return Pair.with(suffixSumList, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0;

    for (int i = n - 1; i >= 0; i--) {
        if (bounds.get(i) < 0) {
            throw new IllegalArgumentException("Elements in the list cannot be less than 0");
        }
        suffixSum.set(i, totalSum);
        totalSum += bounds.get(i);
    }

    suffixSum.set(n - 1, totalSum);

    return new Pair<>(suffixSum, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.with(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>(Collections.nCopies(bounds.size(), 0));
    long totalSum = bounds.stream().mapToLong(Integer::longValue).sum();

    for (int i = bounds.size() - 1; i >= 0; i--) {
        if (i == bounds.size() - 1) {
            suffixSum.set(i, bounds.get(i));
        } else {
            suffixSum.set(i, bounds.get(i) + suffixSum.get(i + 1));
        }
    }

    return Pair.with(suffixSum, totalSum);
}

