        if (bounds == null) {
            throw new IllegalArgumentException("Input bounds list cannot be null");
        }

        int n = bounds.size();
        if (n == 0) {
            return new Pair<>(Collections.emptyList(), 0L);
        }

        List<Integer> suffixSum = new ArrayList<>(n);
        long totalSum = 0;

        for (int i = n - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            suffixSum.add(0, (i == n - 1) ? totalSum : totalSum);
        }

        return new Pair<>(suffixSum, totalSum);
    }

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long totalSum = 0L;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        suffixSum.add(i == bounds.size() - 1 ? bounds.get(i) : bounds.get(i) + suffixSum.get(suffixSum.size() - 1));
    }

    Collections.reverse(suffixSum);
    return new Pair<>(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range specified");
    }

    int left = from;
    int right = to;
    while (left < right) {
        // Swap elements
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        left++;
        right--;
    }
}

